<?php $post=$post??[]; ?><form class="editor-form" method="post" enctype="multipart/form-data" action="<?= $post && !empty($post['id'])?url('/admin/posts/'.$post['id']):url('/admin/posts') ?>"><?= csrf_field() ?><?php if($error):?><div class="form-error full"><?= e($error) ?></div><?php endif;?><section class="form-main admin-panel"><h2>Contenido de la noticia</h2><label>Título *<input name="title" required maxlength="180" value="<?= e($post['title']??'') ?>" placeholder="Escribe un título claro e informativo"></label><label>URL amigable<input name="slug" value="<?= e($post['slug']??'') ?>" placeholder="se-genera-desde-el-titulo"></label><label>Bajada o resumen<textarea name="excerpt" rows="3" maxlength="350" placeholder="Resumen que aparecerá en las tarjetas"><?= e($post['excerpt']??'') ?></textarea></label><label>Contenido *<textarea name="body" rows="14" required placeholder="Escribe aquí el cuerpo completo de la noticia..."><?= e($post['body']??'') ?></textarea></label></section><aside><section class="admin-panel"><h2>Publicación</h2><label>Estado<select name="status"><option value="draft" <?= ($post['status']??'')==='draft'?'selected':'' ?>>Borrador</option><option value="published" <?= ($post['status']??'published')==='published'?'selected':'' ?>>Publicada</option></select></label><label>Fecha y hora<input type="datetime-local" name="published_at" value="<?= e(isset($post['published_at'])?date('Y-m-d\TH:i',strtotime($post['published_at'])):date('Y-m-d\TH:i')) ?>"></label><label class="check"><input type="checkbox" name="featured" value="1" <?= !empty($post['featured'])?'checked':'' ?>> Destacar en portada</label><button class="primary-button">Guardar noticia →</button></section><section class="admin-panel"><h2>Clasificación</h2><label>Categoría<select name="category_id" required><?php foreach($categories as $category):?><option value="<?= $category['id'] ?>" <?= (int)($post['category_id']??0)===(int)$category['id']?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach;?></select></label></section><section class="admin-panel"><h2>Imagen principal</h2><label>Subir imagen<input type="file" name="upload" accept="image/jpeg,image/png,image/webp"></label><span class="hint">JPG, PNG o WebP. Máximo 5 MB.</span><label>o URL externa<input type="url" name="image" value="<?= e($post['image']??'') ?>" placeholder="https://..."></label></section></aside></form>

